      });
    });

    it("starts a new session for a cookie sealed with a password that is not listed", async () => {
      t.app.all("/rotate", rotatingHandler(rotatedConfig));
      const sealed = await sealedAt(otherPassword);
      const res = await t.fetch("/rotate", { headers: { Cookie: `h3-test=${sealed}` } });
      expect(res.status).toBe(200);
      const body = await res.json();
      expect(body.session.id).not.toBe("old");
      expect(body.session.data).toEqual({});
    });

    it("expires a session sealed with an extra password once past maxAge", async () => {
      t.app.all("/rotate-max", rotatingHandler({ ...rotatedConfig, maxAge: 60 }));
      // Control: a fresh session sealed with the same extra password is opened
      const fresh = await sealedAt(oldPassword);
      const freshRes = await t.fetch("/rotate-max", { headers: { Cookie: `h3-test=${fresh}` } });
      expect(await freshRes.json()).toMatchObject({ session: { id: "old" } });

      const sealed = await sealedAt(oldPassword, Date.now() - 120_000);
      const res = await t.fetch("/rotate-max", { headers: { Cookie: `h3-test=${sealed}` } });
      const body = await res.json();
      expect(body.session.id).not.toBe("old");
      expect(body.session.data).toEqual({});
    });

    it("reads a session sealed with an extra password from the session header", async () => {
      t.app.all("/rotate", rotatingHandler(rotatedConfig));
      const sealed = await sealedAt(oldPassword);
      const res = await t.fetch("/rotate", { headers: { "x-h3-test-session": sealed } });
      expect(await res.json()).toMatchObject({ session: { id: "old", data: { foo: "old" } } });
    });

    it("unseals a 1-iteration legacy session with an extra password and reseals it", async () => {
      t.app.all("/rotate", rotatingHandler(rotatedConfig));
      const legacySealed = await seal(
        { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
        oldPassword,
        {
          ...sealDefaults,
          encryption: { ...sealDefaults.encryption, iterations: 1 },
          integrity: { ...sealDefaults.integrity, iterations: 1 },
        },
      );
      const res = await t.fetch("/rotate", { headers: { Cookie: `h3-test=${legacySealed}` } });
      expect(await res.json()).toMatchObject({ session: { id: "legacy", data: { foo: "legacy" } } });

      const resealed = sessionCookie(res);
      expect(await unseal(resealed, newPassword, sealDefaults)).toMatchObject({
        id: "legacy",
        data: { foo: "legacy" },
      });
    });

    it("does not swallow a short extra password that comes before the right one", async () => {
      const config: SessionConfig = {
        name: "h3-test",
        password: newPassword,
        extraUnsealPasswords: ["curta", oldPassword],
      };
      const sealed = await sealedAt(oldPassword);
      await expect(unsealSession({} as HTTPEvent, config, sealed)).rejects.toThrow(
        "Password string too short",
      );
    });

    it("stops at an error other than Bad hmac value and does not try the next password", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const expired = await seal({ id: "old", createdAt: t0, data: {} }, oldPassword, {
          ...sealDefaults,
          ttl: 1,
        });
        vi.setSystemTime(t0 + 600_000);
        const config: SessionConfig = {
          name: "h3-test",
          password: newPassword,
          extraUnsealPasswords: [oldPassword, otherPassword],
        };
        await expect(unsealSession({} as HTTPEvent, config, expired)).rejects.toThrow(
          "Expired seal",
        );
      } finally {
        vi.useRealTimers();
      }
    });

    it("counts PBKDF2 derivations for a cookie no password opens", async () => {
      // Observed: each password costs 2 derivations for the full attempt
      // (encryption + integrity) and 2 more for the 1-iteration legacy retry,
      // so 3 passwords (password + 2 extras) give 12.
      const config: SessionConfig = {
        name: "h3-test",
        password: newPassword,
        extraUnsealPasswords: [otherPassword, oldPassword],
      };
      const sealed = await seal({ id: "x", createdAt: Date.now(), data: {} }, "desconhecida-1234567123456712345671234567123456712345", sealDefaults);
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      try {
        await expect(unsealSession({} as HTTPEvent, config, sealed)).rejects.toThrow(
          "Bad hmac value",
        );
        expect(deriveBits).toHaveBeenCalledTimes(12);
      } finally {
        deriveBits.mockRestore();
      }
    });
  });

  describe("lazy creation", () => {
    const lazyConfig: SessionConfig = {
      name: "h3-lazy",
      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });
});

